import { useEffect, useState } from 'react'

const CONFIG_ROUTE = '/config'
const CONFIG_ROUTE_HASH = `#${CONFIG_ROUTE}`

export interface AppLocation {
    hash: string
    pathname: string
}

function readLocation(): AppLocation {
    const routeHash = window.location.hash
    if (routeHash === CONFIG_ROUTE_HASH) return { hash: '', pathname: CONFIG_ROUTE }
    if (routeHash.startsWith(`${CONFIG_ROUTE_HASH}/`)) {
        return { hash: `#${routeHash.slice(CONFIG_ROUTE_HASH.length + 1)}`, pathname: CONFIG_ROUTE }
    }

    return { hash: routeHash, pathname: '/' }
}

export function navigateTo(path: string) {
    if (path !== '/' && path !== CONFIG_ROUTE) throw new Error(`Unsupported app route: ${path}`)

    window.location.hash = path === '/' ? '' : path
    window.dispatchEvent(new Event('hashchange'))
}

export function useAppLocation() {
    const [location, setLocation] = useState<AppLocation>(readLocation)

    useEffect(() => {
        const handleLocationChange = () => {
            setLocation(readLocation())
        }

        window.addEventListener('hashchange', handleLocationChange)
        window.addEventListener('popstate', handleLocationChange)

        return () => {
            window.removeEventListener('hashchange', handleLocationChange)
            window.removeEventListener('popstate', handleLocationChange)
        }
    }, [])

    return location
}

import { Box, useMediaQuery, useTheme } from '@mui/material'
import { useCallback, useMemo, useState, type ReactNode } from 'react'
import { navigateTo, useAppLocation } from '../../app/app_navigation'
import type { UseGithubAuthResult } from '../../auth/use_github_auth'
import { ConfigPage } from '../config/config_page'
import { useProjectState } from '../hooks/use_project_state'
import { ProjectWorkspace } from '../project_workspace'
import { createSearchRegexpAgent, isSearchRegexpAgentAvailable } from '../../services/search/search_regexp_agent'
import { AppMenu } from './menu/app_menu'
import { SearchControl } from './search/search_control'
import { StatusBar } from './status_bar'

interface MainWindowProps {
    auth: UseGithubAuthResult
    toolbarAction: ReactNode
}

/** Main window: owns the global layout and switches between desktop and mobile presentations. */
export function MainWindow(props: MainWindowProps) {
    const { auth, toolbarAction } = props
    const location = useAppLocation()
    const theme = useTheme()
    const isMobile = useMediaQuery(theme.breakpoints.down('md'))
    const [isMenuOpen, setIsMenuOpen] = useState(false)
    const { project } = useProjectState()
    const isConfigPage = location.pathname === '/config'
    const regexpAgent = useMemo(
        () => isSearchRegexpAgentAvailable() ? createSearchRegexpAgent() : undefined,
        [],
    )

    const handleOpenMenu = useCallback(() => {
        setIsMenuOpen(true)
    }, [])

    const handleCloseMenu = useCallback(() => {
        setIsMenuOpen(false)
    }, [])

    const handleOpenConfig = useCallback(() => {
        navigateTo('/config')
    }, [])

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
            <AppMenu
                accessToken={auth.accessToken}
                auth={auth}
                extraActions={toolbarAction}
                isGithubAuthenticated={auth.isAuthenticated}
                isMobile={isMobile}
                onOpenConfig={handleOpenConfig}
                onOpenMobileMenu={handleOpenMenu}
                search={<SearchControl isMobile={isMobile} regexpAgent={regexpAgent} />}
            />
            {isConfigPage ? (
                <ConfigPage hash={location.hash} />
            ) : (
                <ProjectWorkspace
                    auth={auth}
                    isMenuOpen={isMenuOpen}
                    key={project ? `${project.id}:${project.branch}` : 'no-project'}
                    onLeftPanelInteraction={handleCloseMenu}
                />
            )}
            {!isConfigPage && !isMobile ? <StatusBar /> : null}
        </Box>
    )
}

import { Box, Button, Stack, Tab, Tabs, Typography, useMediaQuery, useTheme } from '@mui/material'
import { useEffect, useMemo, useRef, useState, useSyncExternalStore } from 'react'
import { navigateTo } from '../../app/app_navigation'
import { CONFIG_SECTIONS, configService, type ConfigEntry, type ConfigKey } from '../../services/config/config_service'
import { writeDesktopConfigToBridge } from '../../services/config/config_persistence'
import { dataService } from '../../services/data/data_service'
import { dialogService } from '../../services/dialog_service'
import { DesktopConfigSection } from './desktop_config_section'
import { ProjectConfigSection } from './project_config_section'
import { ReactConfigSection } from './react_config_section'
import { useAppTheme } from '../../theme/use_app_theme'
import {
    cloneMarkdownStyleConfig,
    isMarkdownStyleConfig,
    isMarkdownStylePresetName,
    type MarkdownStyleConfig,
    type MarkdownStyleName,
} from '../../theme/theme_config'
import { MarkdownConfigSection } from './markdown_config_section'

const CONFIG_PAGE_PADDING = 3
const CONFIG_FORM_MAX_WIDTH = 720
const CONFIG_SIDEBAR_WIDTH = 220
const DRAFT_DISCARD_DELAY_MS = 0
const MARKDOWN_CONFIG_SECTION = { id: 'markdown', label: 'Markdown' }

interface MarkdownStyleDraft {
    config: MarkdownStyleConfig
    name: MarkdownStyleName
}

interface ConfigPageProps {
    hash: string
}

function getActiveSection(hash: string, sections: typeof CONFIG_SECTIONS) {
    if (sections.length === 0) throw new Error('Config page requires at least one visible section')

    const section = hash.replace('#', '')
    if (sections.some((item) => item.id === section)) return section

    return sections[0].id
}

function getVisibleSections(entries: ConfigEntry[]) {
    return CONFIG_SECTIONS.flatMap((section) => {
        const visibleSection = entries.some((entry) => entry.section === section.id) ? [section] : []
        return section.id === 'react' ? [...visibleSection, MARKDOWN_CONFIG_SECTION] : visibleSection
    })
}

function getConfigDraftSnapshot() {
    return configService.getDraft()
}

function subscribeToConfigChanges(onStoreChange: () => void) {
    configService.addEventListener('changed', onStoreChange)

    return () => configService.removeEventListener('changed', onStoreChange)
}

export function ConfigPage(props: ConfigPageProps) {
    const { hash } = props
    const theme = useTheme()
    const isMobile = useMediaQuery(theme.breakpoints.down('md'))
    const {
        markdownStyle,
        markdownStyleConfig,
        setCustomMarkdownStyle,
        setMarkdownStyle,
    } = useAppTheme()
    const draft = useSyncExternalStore(subscribeToConfigChanges, getConfigDraftSnapshot)
    const [invalidConfigKeys, setInvalidConfigKeys] = useState<Set<ConfigKey>>(() => new Set())
    const [markdownStyleDraft, setMarkdownStyleDraft] = useState<MarkdownStyleDraft>(() => ({
        config: cloneMarkdownStyleConfig(markdownStyleConfig),
        name: markdownStyle,
    }))
    const draftDiscardTimeoutRef = useRef<number | null>(null)
    const entries = configService.getEntries()
    const visibleSections = useMemo(() => getVisibleSections(entries), [entries])
    const activeSection = getActiveSection(hash, visibleSections)
    const markdownStyleChanged = markdownStyleDraft.name !== markdownStyle
        || JSON.stringify(markdownStyleDraft.config) !== JSON.stringify(markdownStyleConfig)
    const markdownStyleValid = isMarkdownStyleConfig(markdownStyleDraft.config)

    useEffect(() => {
        if (draftDiscardTimeoutRef.current !== null) {
            window.clearTimeout(draftDiscardTimeoutRef.current)
            draftDiscardTimeoutRef.current = null
        }

        const currentDraft = configService.getDraft()
        if (!currentDraft) configService.loadDraft()
        return () => {
            // React StrictMode mounts, unmounts, and remounts effects; delay discard so the remount can cancel it.
            draftDiscardTimeoutRef.current = window.setTimeout(() => {
                configService.discardDraft()
                draftDiscardTimeoutRef.current = null
            }, DRAFT_DISCARD_DELAY_MS)
        }
    }, [])

    if (!draft) return null

    const handleValueChange = (key: ConfigKey, value: unknown) => {
        try {
            if (
                key === 'project.cardSeparator'
                && value !== draft[key]
                && value !== configService.get('project.cardSeparator')
            ) {
                dialogService.warning(
                    'Saving this change will rename existing card files and update their IDs.',
                    { critical: true, title: 'Card files will be renamed' },
                )
            }
            configService.setDraftValue(key, value)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Invalid config value' })
        }
    }

    const handleValidityChange = (key: ConfigKey, valid: boolean) => {
        setInvalidConfigKeys((currentKeys) => {
            if (valid && !currentKeys.has(key)) return currentKeys
            if (!valid && currentKeys.has(key)) return currentKeys

            const nextKeys = new Set(currentKeys)
            if (valid) nextKeys.delete(key)
            else nextKeys.add(key)

            return nextKeys
        })
    }

    const handleMarkdownStyleChange = (name: MarkdownStyleName, config: MarkdownStyleConfig) => {
        setMarkdownStyleDraft({ config, name })
    }

    const handleSaveClick = async () => {
        try {
            const shouldSaveProjectConfig = configService.hasDraftChangesForSource('project')
            const shouldSaveDesktopConfig = configService.hasDraftChangesForSource('desktop')
            const previousCardSeparator = configService.get('project.cardSeparator')
            const nextCardSeparator = draft['project.cardSeparator']
            const shouldUpdateCardSeparator = configService.hasProjectConfig()
                && previousCardSeparator !== nextCardSeparator
            if (shouldUpdateCardSeparator) {
                await dataService.projectLoading.updateCardSeparator(previousCardSeparator, nextCardSeparator)
            }
            configService.saveDraft()
            configService.loadDraft()
            if (markdownStyleChanged && markdownStyleDraft.name === 'custom') setCustomMarkdownStyle(markdownStyleDraft.config)
            else if (markdownStyleChanged && isMarkdownStylePresetName(markdownStyleDraft.name)) {
                setMarkdownStyle(markdownStyleDraft.name)
            }
            if (shouldSaveProjectConfig && configService.hasProjectConfig()) await dataService.projectLoading.saveProjectConfig()
            if (shouldSaveDesktopConfig && configService.hasDesktopConfig()) writeDesktopConfigToBridge(configService.getDesktopValues())
            dialogService.success('Config saved')
            navigateTo('/')
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Config save failed' })
        }
    }

    const handleCancelClick = () => {
        configService.discardDraft()
        navigateTo('/')
    }

    const sectionProps = {
        draft,
        entries,
        onChange: handleValueChange,
        onValidityChange: handleValidityChange,
    }

    const sectionTabs = (
        <Tabs
            aria-label="Config sections"
            orientation={isMobile ? 'horizontal' : 'vertical'}
            scrollButtons="auto"
            value={activeSection}
            variant="scrollable"
        >
            {visibleSections.map((section) => (
                <Tab component="a" href={`#/config/${section.id}`} key={section.id} label={section.label} value={section.id} />
            ))}
        </Tabs>
    )

    return (
        <Box
            aria-label="Config page"
            component="section"
            sx={{ display: 'flex', flex: 1, minHeight: 0, overflow: 'hidden' }}
        >
            {!isMobile ? (
                <Box
                    aria-label="Config section navigation"
                    component="nav"
                    sx={{ borderRight: 1, borderColor: 'divider', flexShrink: 0, minHeight: 0, overflow: 'auto', width: CONFIG_SIDEBAR_WIDTH }}
                    tabIndex={0}
                >
                    {sectionTabs}
                </Box>
            ) : null}
            <Box
                aria-label="Config section content"
                role="region"
                sx={{ flex: 1, minHeight: 0, minWidth: 0, overflow: 'auto', p: CONFIG_PAGE_PADDING }}
                tabIndex={0}
            >
                <Stack spacing={3} sx={{ maxWidth: CONFIG_FORM_MAX_WIDTH }}>
                    <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} sx={{ alignItems: { sm: 'center' } }}>
                        <Typography component="h2" sx={{ flexGrow: 1 }} variant="h5">
                            Config
                        </Typography>
                        <Button onClick={handleCancelClick} variant="outlined">
                            Cancel
                        </Button>
                        <Button disabled={invalidConfigKeys.size > 0 || !markdownStyleValid} onClick={handleSaveClick} variant="contained">
                            Save
                        </Button>
                    </Stack>

                    {isMobile ? sectionTabs : null}

                    {activeSection === 'react' ? <ReactConfigSection {...sectionProps} /> : null}
                    {activeSection === 'markdown' ? (
                        <MarkdownConfigSection
                            config={markdownStyleDraft.config}
                            name={markdownStyleDraft.name}
                            onChange={handleMarkdownStyleChange}
                        />
                    ) : null}
                    {activeSection === 'project' ? <ProjectConfigSection {...sectionProps} /> : null}
                    {activeSection === 'desktop' ? <DesktopConfigSection {...sectionProps} disabled={!configService.hasDesktopConfig()} /> : null}
                </Stack>
            </Box>
        </Box>
    )
}

import { Box } from '@mui/material'
import type { ReactNode } from 'react'
import { useEffect, useRef } from 'react'
import { workspaceViewService } from '../../services/project/workspace_view_service'

interface MobileLayoutProps {
    content: ReactNode
}

/** Mobile body layout: a single panel that is only visible while the text view mode is active. */
export function MobileLayout(props: MobileLayoutProps) {
    const { content } = props
    const containerRef = useRef<HTMLDivElement>(null)

    useEffect(() => {
        const updateVisibility = () => {
            const container = containerRef.current
            if (!container) throw new Error('Missing mobile layout container')

            container.style.display = workspaceViewService.getSnapshot().viewMode === 'text' ? 'flex' : 'none'
        }

        updateVisibility()
        workspaceViewService.addEventListener('changed', updateVisibility)

        return () => workspaceViewService.removeEventListener('changed', updateVisibility)
    }, [])

    return (
        <Box ref={containerRef} sx={{ display: 'flex', flex: 1, minHeight: 0, overflow: 'hidden' }}>
            <Box sx={{ flex: 1, minWidth: 0, overflow: 'auto' }}>
                {content}
            </Box>
        </Box>
    )
}

import { Box, Button, Divider, MenuItem, Tab as MuiTab, Tabs, TextField, ToggleButton, ToggleButtonGroup, Tooltip } from '@mui/material'
import type { SelectChangeEvent } from '@mui/material'
import type { ChangeEvent, MouseEvent as ReactMouseEvent, ReactNode, SyntheticEvent } from 'react'
import { useCallback, useState } from 'react'
import CardsOutline from 'mdi-material-ui/CardsOutline'
import CheckCircleOutline from 'mdi-material-ui/CheckCircleOutline'
import CloudArrowDownOutline from 'mdi-material-ui/CloudArrowDownOutline'
import CloudArrowUpOutline from 'mdi-material-ui/CloudArrowUpOutline'
import Cog from 'mdi-material-ui/Cog'
import ContentSaveOutline from 'mdi-material-ui/ContentSaveOutline'
import FileDocumentPlusOutline from 'mdi-material-ui/FileDocumentPlusOutline'
import FolderOpen from 'mdi-material-ui/FolderOpen'
import TextBoxOutline from 'mdi-material-ui/TextBoxOutline'
import { defaultModelForProfile, findAgentProfile, mergeAgentProfiles, THINKING_LEVELS, validateThinkingLevel } from '../../../data/agent_profiles'
import { configService } from '../../../services/config/config_service'
import { writeDesktopConfigToBridge } from '../../../services/config/config_persistence'
import { projectSessionService } from '../../../services/project/project_session_service'
import { workspaceViewService, type WorkspaceViewMode } from '../../../services/project/workspace_view_service'
import { workspaceNavigationService } from '../../../services/project/workspace_navigation_service'
import { actionService } from '../../../services/actions/action_service'
import { dialogService } from '../../../services/dialog_service'
import { projectContext } from '../../../data/action_context'
import type { UseGithubAuthResult } from '../../../auth/use_github_auth'
import { useConfigValue, useHasDesktopConfig } from '../../hooks/use_config_value'
import { useProjectState } from '../../hooks/use_project_state'
import { useProjectPersistence } from '../../hooks/use_project_persistence'
import { useProjectConfig } from '../../hooks/use_project_config'
import { usePrimaryWorktreeStatus } from '../../hooks/use_worktrees'
import { useWorkspaceView } from '../../hooks/use_workspace_view'
import { ActionEntryPoints } from '../../actions/action_entry_points'
import { MainToolbar } from './main_toolbar'
import { GithubAuthToolbarButton } from '../github_auth_toolbar_button'
import { NO_DRAG_REGION } from '../drag_region'
import { BranchSwitchDialog } from '../project/branch_switch_dialog'
import { CompleteReleaseDialog } from '../project/complete_release_dialog'
import { NewCardDialog } from '../project/new_card_dialog'
import { ProjectOpenDialog } from '../project/project_open_dialog'
import { useProjectToolbarMenuActions } from '../project/use_project_toolbar_menu_actions'
import { Menu } from './menu'
import { BranchMenuSelect } from './branch_menu_select'
import { MenuIconButton } from './menu_icon_button'
import { MenuSelect } from './menu_select'
import { MobileCreateMenu } from './mobile_create_menu'
import { Section } from './section'
import { Tab } from './tab'

type AppMenuTab = 'home' | 'agents'
type ProjectDialogMode = 'open' | 'branch' | 'card' | 'release'

interface AppMenuProps {
    accessToken: string | null
    auth: UseGithubAuthResult
    extraActions: ReactNode
    isGithubAuthenticated: boolean
    isMobile: boolean
    onOpenConfig: () => void
    onOpenMobileMenu: () => void
    search: ReactNode
}

const MENU_TABS: { label: string; value: AppMenuTab }[] = [
    { label: 'Home', value: 'home' },
    { label: 'Run', value: 'agents' },
]
const PROJECT_CONTEXT = projectContext()

function persistDesktopConfig() {
    if (!configService.hasDesktopConfig()) return

    writeDesktopConfigToBridge(configService.getDesktopValues())
}

/** Tabbed app menu hosting project, account and agent actions. */
export function AppMenu(props: AppMenuProps) {
    const { accessToken, auth, extraActions, isGithubAuthenticated, isMobile, onOpenConfig, onOpenMobileMenu, search } = props
    const { project } = useProjectState()
    const { hasPendingPush, hasPendingSave } = useProjectPersistence()
    const primaryWorktreeStatus = usePrimaryWorktreeStatus()
    const projectConfig = useProjectConfig()
    const { viewMode } = useWorkspaceView()
    const [currentTab, setCurrentTab] = useState<AppMenuTab>('home')
    const [dialogMode, setDialogMode] = useState<ProjectDialogMode | null>(null)
    const agentProfiles = mergeAgentProfiles(useConfigValue('desktop.agentProfiles'))
    const selectedAgent = useConfigValue('desktop.agent')
    const selectedProfile = findAgentProfile(agentProfiles, selectedAgent)
    const selectedModels = selectedProfile?.models ?? []
    const configuredModel = useConfigValue('desktop.model')
    const selectedThinkingLevel = useConfigValue('desktop.thinkingLevel')
    const desktopAvailable = useHasDesktopConfig()
    const selectedModel = configuredModel || (selectedProfile ? defaultModelForProfile(selectedProfile) : '')
    const projectBranch = project?.branch ?? ''

    const closeDialog = useCallback(() => {
        setDialogMode(null)
    }, [])

    const openDialog = useCallback((mode: ProjectDialogMode) => {
        setDialogMode(mode)
    }, [])

    const actions = useProjectToolbarMenuActions({
        accessToken,
        isGithubAuthenticated,
        onCloseDialog: closeDialog,
        onOpenDialog: openDialog,
    })
    const branchOptions = actions.branches.length > 0 ? actions.branches : (project ? [{ name: project.branch }] : [])
    const selectedBranch = branchOptions.some((branch) => branch.name === actions.switchBranch) ? actions.switchBranch : projectBranch

    const handleTabChange = (_event: SyntheticEvent, value: AppMenuTab) => {
        setCurrentTab(value)
    }

    const handleOpenProject = () => {
        actions.openProjectDialog()
    }

    const handleCreateProjectFolders = (projectFolder: string) => {
        void actions.createProjectFolders(projectFolder)
    }

    const handleLoadBranches = () => {
        void actions.loadSwitchBranches()
    }

    const handleBranchChange = (event: SelectChangeEvent) => {
        void actions.switchProjectBranch(event.target.value)
    }

    const handleOpenReleaseDialog = () => {
        openDialog('release')
    }

    const handleOpenCardDialog = () => {
        openDialog('card')
    }

    const handleCommit = async () => {
        try {
            await actions.commit()
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }

    const handlePush = async () => {
        try {
            await actions.push()
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }

    const handlePull = async () => {
        try {
            await actions.pull()
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }

    const handleViewModeChange = (_event: ReactMouseEvent<HTMLElement>, nextMode: WorkspaceViewMode | null) => {
        if (!nextMode) return

        workspaceViewService.setViewMode(nextMode)
    }

    const handleAgentChange = (event: SelectChangeEvent) => {
        const profile = findAgentProfile(agentProfiles, event.target.value)
        const nextModel = profile ? defaultModelForProfile(profile) : ''
        configService.set('desktop.agent', event.target.value)
        configService.set('desktop.model', nextModel)
        persistDesktopConfig()
    }

    const setModel = (value: string) => {
        configService.set('desktop.model', value)
        persistDesktopConfig()
    }

    const handleModelSelectChange = (event: SelectChangeEvent) => {
        setModel(event.target.value)
    }

    const handleModelTextChange = (event: ChangeEvent<HTMLInputElement>) => {
        setModel(event.target.value)
    }

    const handleThinkingLevelChange = (event: SelectChangeEvent) => {
        const thinkingLevel = validateThinkingLevel(event.target.value, 'Default reasoning level')
        configService.set('desktop.thinkingLevel', thinkingLevel)
        persistDesktopConfig()
    }

    const handleCreateAction = async () => {
        if (!projectConfig) throw new Error('Cannot create an action before project config is loaded')

        try {
            const { definition, path } = actionService.createDefinition(projectConfig.actionsFolder)
            await actionService.saveDefinition(path, definition)
            workspaceViewService.setViewMode('text')
            workspaceNavigationService.open(path)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Action creation failed' })
        }
    }

    const handleDiscardGithubPendingCommits = () => {
        if (!actions.pendingGithubConflictProject) return

        projectSessionService.discardGithubPendingCommits(actions.pendingGithubConflictProject, accessToken)
    }

    const menuTabs = (
        <Tabs
            aria-label="Application menu"
            onChange={handleTabChange}
            scrollButtons={false}
            sx={{
                minHeight: 44,
                '& .MuiTabs-indicator': { height: 2 },
            }}
            value={currentTab}
            variant="scrollable"
        >
            {MENU_TABS.map((tab) => (
                <MuiTab
                    key={tab.value}
                    label={tab.label}
                    sx={{ fontSize: 13.5, minHeight: 44, minWidth: 0, px: 1.5, textTransform: 'none' }}
                    value={tab.value}
                />
            ))}
        </Tabs>
    )

    const viewSection = (
        <Section label="View">
            <ToggleButtonGroup
                exclusive
                onChange={handleViewModeChange}
                size="small"
                sx={{
                    bgcolor: 'action.selected',
                    borderRadius: 1,
                    gap: 0.25,
                    p: 0.375,
                    '& .MuiToggleButtonGroup-grouped': { border: 0, borderRadius: '6px !important', height: 28, px: 1.25 },
                    '& .Mui-selected': { bgcolor: 'background.paper', boxShadow: '0 1px 2px rgba(16,24,40,0.1)' },
                }}
                value={viewMode}
            >
                <Tooltip title="Cards view">
                    <ToggleButton aria-label="Cards view" value="cards">
                        <CardsOutline fontSize="small" />
                        <Box component="span" sx={{ ml: 0.75 }}>Board</Box>
                    </ToggleButton>
                </Tooltip>
                <Tooltip title="Text view">
                    <ToggleButton aria-label="Text view" value="text">
                        <TextBoxOutline fontSize="small" />
                        <Box component="span" sx={{ ml: 0.75 }}>List</Box>
                    </ToggleButton>
                </Tooltip>
            </ToggleButtonGroup>
        </Section>
    )

    const menuPanel = (
        <Menu>
            <Box role="tabpanel" sx={{ display: currentTab === 'home' ? 'block' : 'none' }}>
                <Tab>
                    {isMobile ? (
                        <>
                            {viewSection}
                            <Divider flexItem orientation="vertical" sx={{ my: 1.5 }} />
                        </>
                    ) : null}
                    <Section label="Project">
                        <MenuIconButton label="Open project" onClick={handleOpenProject}>
                            <FolderOpen fontSize="small" />
                        </MenuIconButton>
                        <BranchMenuSelect
                            branches={branchOptions}
                            disabled={!actions.isProjectOpen || actions.isLoading}
                            onChange={handleBranchChange}
                            onOpen={handleLoadBranches}
                            value={selectedBranch}
                        />
                        <MenuIconButton
                            disabled={!actions.isProjectOpen || actions.isLoading || !hasPendingSave}
                            label="Commit"
                            onClick={handleCommit}
                        >
                            <ContentSaveOutline fontSize="small" />
                        </MenuIconButton>
                        <MenuIconButton
                            disabled={
                                !actions.isProjectOpen
                                || actions.isLoading
                                || (!hasPendingPush && (primaryWorktreeStatus?.ahead ?? 0) <= 0)
                            }
                            label="Push"
                            onClick={handlePush}
                        >
                            <CloudArrowUpOutline fontSize="small" />
                        </MenuIconButton>
                        <MenuIconButton
                            disabled={
                                !actions.isProjectOpen
                                || actions.isLoading
                                || hasPendingSave
                                || hasPendingPush
                                || !primaryWorktreeStatus?.hasUpstream
                                || primaryWorktreeStatus.dirty
                                || primaryWorktreeStatus.ahead > 0
                                || primaryWorktreeStatus.behind <= 0
                            }
                            label="Pull"
                            onClick={handlePull}
                        >
                            <CloudArrowDownOutline fontSize="small" />
                        </MenuIconButton>
                    </Section>
                    <Divider flexItem orientation="vertical" sx={{ my: 1.5 }} />
                    <Section label="Settings">
                        <MenuIconButton label="Config" onClick={onOpenConfig}>
                            <Cog fontSize="small" />
                        </MenuIconButton>
                        {extraActions}
                    </Section>
                    {!isMobile ? (
                        <>
                            <Divider flexItem orientation="vertical" sx={{ my: 1.5 }} />
                            {viewSection}
                            <Divider flexItem orientation="vertical" sx={{ my: 1.5 }} />
                            <Button disabled={!project} onClick={handleCreateAction} size="small" variant="outlined">New action</Button>
                            <Button
                                disabled={!actions.isProjectOpen}
                                onClick={handleOpenCardDialog}
                                size="small"
                                startIcon={<FileDocumentPlusOutline fontSize="small" />}
                                sx={{ height: 34, px: 1.75 }}
                                variant="contained"
                            >
                                New card
                            </Button>
                            <Box sx={{ flex: 1 }} />
                            <Section label="Account">
                                <GithubAuthToolbarButton auth={auth} />
                            </Section>
                        </>
                    ) : null}
                </Tab>
            </Box>
            <Box role="tabpanel" sx={{ display: currentTab === 'agents' ? 'block' : 'none' }}>
                <Tab>
                    <Section label="Setup">
                        <MenuSelect
                            disabled={!desktopAvailable}
                            label="Default agent"
                            minWidth={130}
                            onChange={handleAgentChange}
                            value={selectedAgent}
                        >
                            {agentProfiles.map((profile) => (
                                <MenuItem key={profile.name} value={profile.name}>{profile.name}</MenuItem>
                            ))}
                        </MenuSelect>
                        {selectedModels.length > 0 ? (
                            <MenuSelect
                                disabled={!desktopAvailable}
                                label="Default model"
                                minWidth={150}
                                onChange={handleModelSelectChange}
                                value={selectedModel}
                            >
                                {selectedModels.map((model) => (
                                    <MenuItem key={model} value={model}>{model}</MenuItem>
                                ))}
                            </MenuSelect>
                        ) : (
                            <Tooltip title="Default model">
                                <TextField
                                    disabled={!desktopAvailable}
                                    onChange={handleModelTextChange}
                                    size="small"
                                    slotProps={{ htmlInput: { 'aria-label': 'Default model' } }}
                                    style={NO_DRAG_REGION}
                                    sx={{ width: 150 }}
                                    value={selectedModel}
                                />
                            </Tooltip>
                        )}
                        <MenuSelect
                            disabled={!desktopAvailable}
                            label="Default reasoning level"
                            minWidth={120}
                            onChange={handleThinkingLevelChange}
                            value={selectedThinkingLevel}
                        >
                            {THINKING_LEVELS.map((level) => (
                                <MenuItem key={level} value={level}>{level}</MenuItem>
                            ))}
                        </MenuSelect>
                    </Section>
                    <Divider flexItem orientation="vertical" sx={{ my: 1.5 }} />
                    <Section label="Actions">
                        <ActionEntryPoints context={PROJECT_CONTEXT} variant="icons" visibility="explicit-context" />
                        <MenuIconButton
                            disabled={!actions.isProjectOpen || actions.activeCards.length === 0 || actions.isReleaseCompleting}
                            label="Complete release"
                            onClick={handleOpenReleaseDialog}
                        >
                            <CheckCircleOutline fontSize="small" />
                        </MenuIconButton>
                    </Section>
                </Tab>
            </Box>
            <ProjectOpenDialog
                branches={actions.branches}
                initialSource={actions.initialProjectSource}
                isDesktopMode={actions.isDesktopMode}
                isGithubAuthenticated={isGithubAuthenticated}
                isLoading={actions.isLoading}
                onCreateProjectFolders={handleCreateProjectFolders}
                projectOpenResolution={actions.projectOpenResolution}
                onBranchChange={() => undefined}
                onClose={actions.closeDialog}
                onCreateRemoteProject={actions.createRemoteProject}
                onCreateWorkingFolder={() => void actions.createWorkingFolder()}
                onDiscardGithubPendingCommits={handleDiscardGithubPendingCommits}
                onLoadManualBranches={actions.loadManualBranches}
                onLoadRemoteBranches={actions.loadRemoteBranches}
                onOpenGithub={actions.openGithubProject}
                onOpenRemote={actions.openRemoteProject}
                onRepositoryChange={actions.loadRepositoryBranches}
                onSourceChange={actions.clearOpenDialogState}
                onUseWorkingFolder={(folder) => void actions.openWorkingFolder(folder)}
                open={dialogMode === 'open'}
                pendingGithubConflictProject={actions.pendingGithubConflictProject}
                repositories={actions.repositories}
            />
            <BranchSwitchDialog
                branches={actions.branches}
                isLoading={actions.isLoading}
                onBranchChange={actions.setSwitchBranch}
                onClose={actions.closeDialog}
                onSwitchBranch={(branch) => void actions.switchProjectBranch(branch)}
                open={dialogMode === 'branch'}
                selectedBranch={actions.switchBranch}
            />
            <CompleteReleaseDialog
                isLoading={actions.isLoading}
                onClose={actions.closeDialog}
                onCompleteRelease={actions.completeRelease}
                open={dialogMode === 'release'}
            />
            <NewCardDialog
                cardBodyTemplate={actions.cardBodyTemplate}
                cardTypes={actions.cardTypes}
                isLoading={actions.isLoading}
                isProjectOpen={actions.isProjectOpen}
                onClose={actions.closeDialog}
                onCreateCard={actions.createCard}
                open={dialogMode === 'card'}
            />
        </Menu>
    )

    return (
        <MainToolbar
            isMobile={isMobile}
            mobileAction={isMobile && currentTab === 'home' ? (
                <MobileCreateMenu
                    isNewActionDisabled={!project}
                    isNewCardDisabled={!actions.isProjectOpen}
                    onCreateAction={handleCreateAction}
                    onCreateCard={handleOpenCardDialog}
                />
            ) : null}
            onOpenMenu={onOpenMobileMenu}
            panel={menuPanel}
            search={search}
            tabs={menuTabs}
        />
    )
}

